def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    codes = [c for c, _ in LANGS[1:]]
    out = {"langs": [{"code": c, "name": n} for c, n in LANGS], "strings": {}}
    for k, v in S.items():
        assert len(v) == len(codes), k
        out["strings"][k] = dict(zip(codes, v))
    with open(os.path.join(root, "web/i18n.json"), "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1, sort_keys=True)
        f.write("\n")

main()
